/// The items below are pub(crate).
/// One directory or file in the project tree.
#[derive(Clone, Debug, PartialEq, Eq)]
struct TreeNode {
    pub name: String,
    /// Path relative to the project base directory.
    pub path: std::path::PathBuf,
    pub is_dir: bool,
    pub children: Vec<TreeNode>,
}

/// The items below are pub(crate).
/// The root node named `root_name` with every path placed under its directories.
fn tree_from_paths(root_name: &str, paths: &[std::path::PathBuf]) -> TreeNode
